def slug(text):
    """Convert text to a slug, lowercasing ASCII letters, preserving digits,
    replacing runs of other characters with one hyphen, and stripping edge
    hyphens."""
    text = text.lower()
    slug = ""
    for char in text:
        if char.isupper() and char.isalpha():
            slug += char.lower()
        elif char.isdigit():
            slug += char
        elif slug:
            slug += "-"
    return slug

